# PTX source for L2‑normalization across dimension 1 (fp16 tensors)
PTX_SOURCE = r'''
.version 7.0
.target sm_80
.address_size 64

.visible .entry l2norm_kernel (
    .param .u64 out_ptr,
    .param .u64 in_ptr,
    .param .u32 batch,
    .param .u32 dim
)
{
    // registers
    .reg .pred   %p<5>;
    .reg .b32    %r<20>;
    .reg .b64    %rd<20>;
    .reg .f32    %f<10>;
    .reg .f16    %h<2>;

    // load kernel parameters
    ld.param.u64    %rd1, [out_ptr];
    ld.param.u64    %rd2, [in_ptr];
    ld.param.u32    %r1, [batch];
    ld.param.u32    %r2, [dim];

    // thread/block identifiers
    mov.u32         %r3, %ctaid.x;      // blockIdx.x  -> row index
    mov.u32         %r4, %ntid.x;       // blockDim.x
    mov.u32         %r5, %tid.x;        // threadIdx.x

    // compute base pointers for this row (row * dim * sizeof(half))
    mul.wide.u32    %rd3, %r3, %r2;     // row * dim (int)
    mul.wide.u32    %rd4, %rd3, 2;      // *2 bytes per half
    add.u64         %rd5, %rd2, %rd4;   // in_ptr + offset
    add.u64         %rd6, %rd1, %rd4;   // out_ptr + offset

    // ------------------------------------------------------------------
    // 1st pass: compute sum of squares (float32 accumulation)
    // ------------------------------------------------------------------
    mov.f32         %f1, 0.0;           // partial sum

    // i = threadIdx.x
    mov.u32         %r6, %r5;
LOOP_SUM:
    setp.ge.u32     %p1, %r6, %r2;
    @%p1 bra        END_LOOP_SUM;

    // load half element
    mul.wide.u32    %rd7, %r6, 2;
    add.u64         %rd8, %rd5, %rd7;
    ld.global.u16   %r7, [%rd8];
    // convert to float16 then to float32
    cvt.f16.u16     %h1, %r7;
    cvt.f32.f16     %f2, %h1;
    // square and accumulate
    mul.f32         %f3, %f2, %f2;
    add.f32         %f1, %f1, %f3;

    // i += blockDim.x
    add.u32         %r6, %r6, %r4;
    bra             LOOP_SUM;
END_LOOP_SUM:

    // ------------------------------------------------------------------
    // Block‑wide reduction of partial sums (shared memory)
    // ------------------------------------------------------------------
    .shared .align 4 .b32 sdata[256];     // adjust to max block size

    // store partial sum to shared memory
    mul.wide.u32    %rd9, %r5, 4;
    add.u64         %rd10, sdata, %rd9;
    st.shared.u32   [%rd10], %f1;

    bar.sync 0;

    // binary tree reduction
    mov.u32         %r8, %r4;            // stride = blockDim.x
REDUCTION_LOOP:
    shr.u32         %r9, %r8, 1;        // stride/2
    setp.eq.u32     %p2, %r9, 0;
    @%p2 bra        REDUCTION_DONE;

    setp.lt.u32     %p3, %r5, %r9;      // if tid < stride/2
    @%p3 {
        // load my value
        mul.wide.u32 %rd11, %r5, 4;
        add.u64     %rd12, sdata, %rd11;
        ld.shared.u32 %r10, [%rd12];
        // load partner value
        add.u32     %r11, %r5, %r9;
        mul.wide.u32 %rd13, %r11, 4;
        add.u64     %rd14, sdata, %rd13;
        ld.shared.u32 %r12, [%rd14];
        // sum and store back to my slot
        add.u32     %r13, %r10, %r12;
        st.shared.u32 [%rd12], %r13;
    }
    bar.sync 0;
    mov.u32         %r8, %r9;
    bra             REDUCTION_LOOP;
REDUCTION_DONE:

    // thread 0 now holds the total sum in sdata[0]
    // load total sum as float
    mov.u32         %r14, 0;
    mul.wide.u32    %rd15, %r14, 4;
    add.u64         %rd16, sdata, %rd15;
    ld.shared.u32   %r15, [%rd16];
    cvt.f32.u32     %f4, %r15;           // total sum (float)

    // compute norm = sqrt(total_sum) and its reciprocal
    sqrt.approx.f32 %f5, %f4;
    rcp.approx.f32  %f6, %f5;            // 1 / norm

    // broadcast reciprocal to all threads via shared memory
    st.shared.f32   [%rd16], %f6;
    bar.sync 0;
    ld.shared.f32   %f7, [%rd16];       // inv_norm

    // ------------------------------------------------------------------
    // 2nd pass: write normalized values
    // ------------------------------------------------------------------
    // i = threadIdx.x
    mov.u32         %r6, %r5;
WRITE_LOOP:
    setp.ge.u32     %p4, %r6, %r2;
    @%p4 bra        END_WRITE;

    // load half element
    mul.wide.u32    %rd7, %r6, 2;
    add.u64         %rd8, %rd5, %rd7;
    ld.global.u16   %r7, [%rd8];
    cvt.f16.u16     %h1, %r7;
    cvt.f32.f16     %f2, %h1;

    // normalize
    mul.f32         %f8, %f2, %f7;

    // convert back to half and store
    cvt.f16.f32     %h2, %f8;
    add.u64         %rd8, %rd6, %rd7;
    st.global.u16   [%rd8], %h2;

    // i += blockDim.x
    add.u32         %r6, %r6, %r4;
    bra             WRITE_LOOP;
END_WRITE:

    ret;
}
'''
# ----------------------------------------------------------------------
# Python wrapper that loads the PTX and launches it
# ----------------------------------------------------------------------
class ModelNew:
    def __init__(self):
        # ptx_load and ptx_launch are provided by the harness
        self.module = ptx_load(PTX_SOURCE)
        self.kernel_name = "l2norm_kernel"

    def forward(self, inputs):
        import torch
        x = inputs[0]                         # fp16 tensor on CUDA
        out = torch.empty_like(x, dtype=torch.float16, device='cuda')
        batch, dim = x.shape
        # launch configuration: one block per batch row, 256 threads per block
        grid = (batch, 1, 1)
        block = (256, 1, 1)
        args = [out.data_ptr(), x.data_ptr(), batch, dim]
        ptx_launch(self.module, self.kernel_name, grid, block, args)
        return [out]
